-- Step 40: approved trainer commercial foundation. No charges or payouts.
-- Hosted migration history is generated by Supabase MCP; this is its source snapshot.
begin;

create schema if not exists monolith_private;
revoke all on schema monolith_private from public;
grant usage on schema monolith_private to authenticated, service_role;

-- Historical status/provider fields were once client-writable. Only a trusted
-- payment handler may establish provenance; no old row is auto-verified.
alter table public.subscriptions add column if not exists server_verified_at timestamptz;

alter table public.app_plans add column if not exists student_limit integer
  check (student_limit is null or student_limit between 0 and 100000);

-- Keep historical keys for foreign keys; retire their public commercial offer.
update public.app_plans set is_public=false where key in ('student_monthly','influencer_free','trainer_plus');
insert into public.app_plans(key,name,role,monthly_price_cents,currency,is_public,features,student_limit)
values
('trainer_basic','Personal Basic','trainer_basic',3499,'USD',true,
 '["students","workouts","diets","checkins","measurements","photos","anamnesis","programs","monthly_reports","calendar","manual_student_billing"]',15),
('trainer_pro','Personal Pro','trainer_basic',4999,'USD',true,
 '["students","workouts","diets","checkins","measurements","photos","anamnesis","programs","monthly_reports","calendar","manual_student_billing"]',50)
on conflict(key) do update set name=excluded.name,role=excluded.role,
  monthly_price_cents=excluded.monthly_price_cents,currency=excluded.currency,
  is_public=excluded.is_public,features=excluded.features,student_limit=excluded.student_limit;

create table public.app_plan_prices (
  plan_key text not null references public.app_plans(key),
  market text not null check(market in ('US','BR')),
  currency text not null check(currency in ('USD','BRL')),
  monthly_price_minor integer not null check(monthly_price_minor>0),
  primary key(plan_key,market),
  check((market='US' and currency='USD') or (market='BR' and currency='BRL'))
);
insert into public.app_plan_prices(plan_key,market,currency,monthly_price_minor) values
 ('trainer_basic','US','USD',3499),('trainer_pro','US','USD',4999),
 ('trainer_basic','BR','BRL',2990),('trainer_pro','BR','BRL',3990);

create table public.monolith_commercial_policy (
  singleton boolean primary key default true check(singleton),
  student_access_included boolean not null default true,
  discovery_free boolean not null default true,
  default_commission_bps integer not null default 1500 check(default_commission_bps between 0 and 10000)
);
insert into public.monolith_commercial_policy(singleton) values(true);

-- Grants preserve access independently of purchase status or editable preferences.
-- They are not paid subscriptions and are never created by end users.
create table public.trainer_access_grants (
  trainer_id uuid primary key references public.profiles(id) on delete cascade,
  grant_kind text not null check(grant_kind in ('legacy','beta')),
  student_limit integer not null check(student_limit between 0 and 100000),
  plan_key text references public.app_plans(key) check(plan_key is null or plan_key in ('trainer_basic','trainer_pro')),
  expires_at timestamptz,
  revoked_at timestamptz,
  created_at timestamptz not null default now()
);
insert into public.trainer_access_grants(trainer_id,grant_kind,student_limit,plan_key)
select p.id,'legacy',greatest(15,(select count(distinct ts.student_id)::int from public.trainer_students ts
  where ts.trainer_id=p.id and ts.status='active')),'trainer_basic'
from public.profiles p where p.role in ('trainer_basic','trainer_plus','admin') and p.access_mode='authenticated';

-- A negotiated agreement is an explicit override, not inferred from an old role.
create table public.influencer_commission_terms (
  influencer_id uuid primary key references public.profiles(id) on delete cascade,
  commission_bps integer not null check(commission_bps between 0 and 10000),
  agreement_reference text not null check(length(btrim(agreement_reference)) between 1 and 500),
  created_at timestamptz not null default now()
);

alter table public.app_plan_prices enable row level security;
alter table public.monolith_commercial_policy enable row level security;
alter table public.trainer_access_grants enable row level security;
alter table public.influencer_commission_terms enable row level security;
create policy commercial_prices_read on public.app_plan_prices for select to anon,authenticated
  using(exists(select 1 from public.app_plans p where p.key=plan_key and p.is_public));
create policy commercial_policy_read on public.monolith_commercial_policy for select to anon,authenticated using(true);
create policy commercial_grant_self on public.trainer_access_grants for select to authenticated using(trainer_id=(select auth.uid()));
create policy commission_terms_self on public.influencer_commission_terms for select to authenticated using(influencer_id=(select auth.uid()));

revoke all on public.app_plans,public.app_plan_prices,public.monolith_commercial_policy,
  public.trainer_access_grants,public.influencer_commission_terms,public.subscriptions from public,anon,authenticated;
grant select on public.app_plans,public.app_plan_prices,public.monolith_commercial_policy to anon,authenticated;
grant select on public.trainer_access_grants,public.influencer_commission_terms,public.subscriptions to authenticated;
grant all on public.app_plans,public.app_plan_prices,public.monolith_commercial_policy,
  public.trainer_access_grants,public.influencer_commission_terms,public.subscriptions to service_role;
drop policy if exists subscriptions_insert_self on public.subscriptions;
drop policy if exists subscriptions_update_self on public.subscriptions;

create function monolith_private.trainer_commercial_access(p_trainer uuid)
returns table(student_limit integer,plan_key text,source text)
language sql stable security definer set search_path='' as $$
  select candidate.student_limit,candidate.plan_key,candidate.source
  from (
    select g.student_limit,g.plan_key,g.grant_kind as source,1 as priority
    from public.trainer_access_grants g
    join public.profiles p on p.id=g.trainer_id
    where g.trainer_id=p_trainer and g.revoked_at is null
      and (g.expires_at is null or g.expires_at>now())
      and p.role in ('trainer_basic','trainer_plus','admin') and p.access_mode='authenticated'
    union all
    select ap.student_limit,ap.key,'subscription'::text,2
    from public.subscriptions s
    join public.app_plans ap on ap.key=s.plan_key
    join public.profiles p on p.id=s.user_id
    where s.user_id=p_trainer and s.status='active' and s.provider in ('stripe','apple','google')
      and s.server_verified_at is not null and s.server_verified_at<=now()
      and s.current_period_start is not null and s.current_period_start<=now()
      and s.current_period_end is not null and s.current_period_end>now()
      and ap.key in ('trainer_basic','trainer_pro') and ap.student_limit is not null
      and p.role in ('trainer_basic','trainer_plus','admin') and p.access_mode='authenticated'
    union all select 0,null::text,'none'::text,0
  ) candidate order by candidate.student_limit desc,candidate.priority desc,candidate.plan_key nulls last limit 1;
$$;
revoke all on function monolith_private.trainer_commercial_access(uuid) from public,anon,authenticated;

create function monolith_private.get_commercial_state() returns jsonb
language plpgsql stable security definer set search_path='' as $$
declare uid uuid:=auth.uid(); profile public.profiles; access record; active_count integer; trainer boolean; begin
  if uid is null then raise exception 'Authentication required' using errcode='42501'; end if;
  select * into profile from public.profiles where id=uid and access_mode='authenticated';
  if profile.id is null then raise exception 'Authenticated profile required' using errcode='42501'; end if;
  trainer:=profile.role in ('trainer_basic','trainer_plus','admin');
  select * into access from monolith_private.trainer_commercial_access(uid);
  select count(distinct student_id)::int into active_count from public.trainer_students where trainer_id=uid and status='active';
  return jsonb_build_object(
    'is_trainer',trainer,'plan_key',access.plan_key,'source',access.source,
    'student_limit',access.student_limit,'active_students',active_count,
    'can_add_student',trainer and active_count<access.student_limit,
    'over_limit',active_count>access.student_limit,'checkout_available',false,
    'policy',(select to_jsonb(c)-'singleton' from public.monolith_commercial_policy c where singleton),
    'prices',(select coalesce(jsonb_agg(to_jsonb(pr) || jsonb_build_object('name',ap.name,'student_limit',ap.student_limit)
      order by pr.market,pr.monthly_price_minor),'[]'::jsonb)
      from public.app_plan_prices pr join public.app_plans ap on ap.key=pr.plan_key where ap.is_public)
  );
end $$;
revoke all on function monolith_private.get_commercial_state() from public,anon,authenticated;
grant execute on function monolith_private.get_commercial_state() to authenticated;

create function public.get_monolith_commercial_state() returns jsonb
language sql stable security invoker set search_path='' as $$
  select monolith_private.get_commercial_state();
$$;
revoke all on function public.get_monolith_commercial_state() from public,anon,authenticated;
grant execute on function public.get_monolith_commercial_state() to authenticated;

-- Keep the existing row lock, ownership guard and idempotent retry behavior.
create or replace function monolith_private.guard_student_capacity() returns trigger
language plpgsql security definer set search_path='' as $$
declare owner_id uuid; owner_role public.monolith_role; capacity integer; begin
  select managed_by into owner_id from public.profiles where id=new.student_id and access_mode='managed';
  if owner_id is not null and owner_id<>new.trainer_id then
    raise exception 'Managed students cannot be shared or transferred' using errcode='42501';
  end if;
  if new.status<>'active' then return new; end if;
  if tg_op='UPDATE' then
    if old.status='active' and old.trainer_id=new.trainer_id and old.student_id=new.student_id then return new; end if;
  end if;
  -- Recount after the trainer lock relies on READ COMMITTED fresh snapshots.
  -- Reject stronger snapshot isolation instead of silently overbooking.
  if current_setting('transaction_isolation')<>'read committed' then
    raise exception 'MONOLITH_CAPACITY_REQUIRES_READ_COMMITTED' using errcode='0A000';
  end if;
  select role into owner_role from public.profiles where id=new.trainer_id for update;
  if owner_role is null or owner_role not in ('trainer_basic','trainer_plus','admin') then
    raise exception 'Only trainers can own students' using errcode='42501';
  end if;
  if exists(select 1 from public.trainer_students where trainer_id=new.trainer_id and student_id=new.student_id and status='active') then return new; end if;
  select student_limit into capacity from monolith_private.trainer_commercial_access(new.trainer_id);
  if coalesce(capacity,0)=0 then raise exception 'MONOLITH_SUBSCRIPTION_REQUIRED' using errcode='P0001'; end if;
  if (select count(distinct student_id) from public.trainer_students where trainer_id=new.trainer_id and status='active')>=capacity then
    raise exception 'MONOLITH_STUDENT_LIMIT' using errcode='P0001';
  end if;
  return new;
end $$;
revoke all on function monolith_private.guard_student_capacity() from public,anon,authenticated;

-- Server-only financial preview. It does not create a receivable, receipt or payout.
create function public.preview_monolith_referral_commission(
  p_influencer_id uuid,p_currency text,p_paid_minor bigint,p_tax_minor bigint,p_channel_fee_minor bigint,p_refund_minor bigint
) returns jsonb language plpgsql stable security invoker set search_path='' as $$
declare rate integer; eligible bigint; commission bigint; deductions numeric; begin
  if p_currency is null or p_currency not in ('USD','BRL') or p_paid_minor is null or p_tax_minor is null
    or p_channel_fee_minor is null or p_refund_minor is null
    or p_paid_minor<0 or p_tax_minor<0 or p_channel_fee_minor<0 or p_refund_minor<0 then
    raise exception 'Invalid commission inputs' using errcode='22023';
  end if;
  if not exists(select 1 from public.profiles where id=p_influencer_id and access_mode='authenticated') then
    raise exception 'Invalid influencer identity' using errcode='22023';
  end if;
  deductions:=p_tax_minor::numeric+p_channel_fee_minor::numeric+p_refund_minor::numeric;
  if deductions>p_paid_minor then raise exception 'Deductions exceed payment' using errcode='22023'; end if;
  select commission_bps into rate from public.influencer_commission_terms where influencer_id=p_influencer_id;
  if rate is null then select default_commission_bps into rate from public.monolith_commercial_policy where singleton; end if;
  if rate is null then raise exception 'Commission policy missing' using errcode='22023'; end if;
  eligible:=(p_paid_minor::numeric-deductions)::bigint;
  commission:=round(eligible::numeric*rate::numeric/10000)::bigint;
  return jsonb_build_object('currency',p_currency,'rate_bps',rate,'eligible_minor',eligible,'commission_minor',commission,'preview_only',true);
end $$;
revoke all on function public.preview_monolith_referral_commission(uuid,text,bigint,bigint,bigint,bigint) from public,anon,authenticated;
grant execute on function public.preview_monolith_referral_commission(uuid,text,bigint,bigint,bigint,bigint) to service_role;

comment on table public.trainer_access_grants is 'Server-owned legacy/beta capacity. Not proof of payment. Review original beta agreements before changing.';
comment on function public.preview_monolith_referral_commission(uuid,text,bigint,bigint,bigint,bigint) is 'Backend-only estimate. Caller must verify payment and attribution before any ledger/payout.';
notify pgrst,'reload schema';
commit;

